def _text(value: Any, where: str) -> str:
    if not isinstance(value, str):
        raise ContractError(f"{where} must be text")
    normalized = " ".join(unicodedata.normalize("NFC", value).split())
    if not normalized or len(normalized) > 160:
        raise ContractError(f"{where} must be 1..160 normalized characters")
    if any(unicodedata.category(ch).startswith("C") for ch in normalized):
        raise ContractError(f"{where} contains control/format characters")
    return normalized


